import importlib


def load_config(text: str) -> dict:
    """Parse a maintainer-authored profile into settings and a plugin instance.

    Each non-blank, non-comment line is ``key = <python expression>``. The
    expression is evaluated (profiles are trusted local files, so arithmetic,
    comprehensions, built-in calls and nested objects all work). The ``plugin``
    key names an installed/project module whose ``Transform`` is instantiated;
    every other key is collected into ``settings``.
    """
    settings = {}
    plugin_name = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, expr = line.partition("=")
        if not sep:
            raise ValueError(f"malformed profile line (missing '='): {raw_line!r}")
        key = key.strip()
        value = eval(expr.strip(), {})  # noqa: S307 - trusted local profile
        if key == "plugin":
            plugin_name = value
        else:
            settings[key] = value

    plugin = None
    if plugin_name:
        module = importlib.import_module(plugin_name)
        plugin = module.Transform()

    return {"settings": settings, "plugin": plugin}
"}
